-- postgresql.conf
-- wal_level = logical
-- max_replication_slots = 4
-- max_wal_senders = 4

-- Create a least-privilege replication user
CREATE ROLE debezium WITH REPLICATION LOGIN PASSWORD 'secret';
GRANT USAGE ON SCHEMA app TO debezium;
GRANT SELECT ON ALL TABLES IN SCHEMA app TO debezium;

-- Publication defining which tables to capture
CREATE PUBLICATION dbz_pub FOR TABLE app.customers, app.orders;

-- Debezium will create the logical replication slot automatically, e.g.:
-- SELECT * FROM pg_create_logical_replication_slot('dbz_slot', 'pgoutput');

-- Monitor slot lag so WAL is not retained indefinitely if the connector is down
SELECT slot_name, active,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_wal
FROM pg_replication_slots;
